export function paintDramaForeground(c,s,images,f){const im=image(images,f,'globeCloud');if(!ready(im)||!f.globeShowClouds)return;const approach=smooth((s.age-4.4)/1.45);c.save();c.beginPath();c.rect(0,0,960,540);c.clip();c.globalCompositeOperation='screen';c.globalAlpha=.07*f.globeCloudDepth*(1-approach*.4);c.filter='none';c.drawImage(colorPlate(im,'#749ed1',true),-740+s.time*27,-340,1500,845);c.drawImage(colorPlate(im,'#db648f',true),400-s.time*32,180,1400,790);c.restore();
 if(approach>0){c.save();c.globalCompositeOperation='screen';c.globalAlpha=approach*f.globeMotionBlur*.11;c.strokeStyle='#d2eaff';c.lineWidth=.7;for(let i=0;i<28;i++){const a=i*2.399,r=250+(i%4)*65,len=10+approach*(35+i%5*9);c.beginPath();c.moveTo(480+Math.cos(a)*r,270+Math.sin(a)*r*.65);c.lineTo(480+Math.cos(a)*(r+len),270+Math.sin(a)*(r+len)*.65);c.stroke()}c.restore();}}
